const e = $json.execution || {}; const w = $json.workflow || {};
const msg = `🚨 **${w.name || 'A workflow'}** failed` + (e.lastNodeExecuted ? ` at node **${e.lastNodeExecuted}**` : '') + `
${(e.error?.message || 'no error message').slice(0, 500)}` + (e.url ? `
${e.url}` : '') + `
mode: ${e.mode || '?'}`;
return [{ json: { content: msg } }];

// One JSON file per night with every workflow (credential secrets are never included by the n8n API)
const day = new Date().toISOString().slice(0, 10);
const drop = ['updatedAt','createdAt','versionId','activeVersionId','triggerCount','shared','homeProject','activeVersion','meta'];
const all = $input.all().map(({ json: w }) => Object.fromEntries(Object.entries(w).filter(([k]) => !drop.includes(k))));
const fileName = `n8n-backup-${day}.json`;
return [{ json: { path: `/home/node/.n8n-files/${fileName}`, count: all.length },
         binary: { data: { data: Buffer.from(JSON.stringify(all, null, 2)).toString('base64'), mimeType: 'application/json', fileName } } }];
